const ANSWERS=['APPLE','BEACH','BRAVE','BREAD','BRICK','CHAIR','CHARM','CHEER','CHEST','CLOUD','CORAL','CRAFT','CRANE','DANCE','DREAM','EARTH','FLAME','FRESH','FRUIT','GIANT','GLASS','GRACE','GRAPE','GREEN','HEART','HONEY','HOUSE','LIGHT','MAGIC','MAPLE','MIRTH','MUSIC','NOBLE','OCEAN','PAINT','PEACE','PEARL','PLANT','PRIDE','QUIET','RADIO','RIVER','ROBIN','ROUND','SHINE','SMILE','SOLAR','SPICE','STAGE','STONE','STORY','SWEET','TABLE','TEACH','TIGER','TRAIN','TRUST','UNITY','WATER','WORLD'];
const EXTRA=['ABOUT','ABOVE','ACTOR','ADULT','AFTER','AGAIN','ALONE','ALONG','ANGEL','ANGER','ARISE','ASIDE','AUDIO','BASIC','BEGIN','BLACK','BLAME','BLIND','BLOCK','BOARD','BRAIN','BRAND','BREAK','BRING','BROWN','BUILD','CARRY','CATCH','CAUSE','CHAIN','CHILD','CHOIR','CLASS','CLEAN','CLEAR','CLIMB','CLOCK','CLOSE','COACH','COAST','COLOR','COUNT','COURT','COVER','CROSS','CROWN','DAILY','DRINK','DRIVE','EAGER','EARLY','FIELD','FIRST','FLOOR','FOCUS','FRAME','FRONT','GREAT','GROUP','GUARD','GUIDE','HAPPY','HORSE','HOTEL','HUMAN','IDEAL','IMAGE','JUICE','KNIFE','LAUGH','LEARN','LEMON','LEVEL','LOVER','LUCKY','MARCH','MATCH','METAL','MONEY','MONTH','MOUSE','MOVIE','NEVER','NIGHT','NORTH','NOVEL','NURSE','OFFER','OTHER','PAPER','PARTY','PHONE','PIANO','PLACE','PLAIN','PLANE','PLATE','POINT','POWER','PRESS','PRICE','PRIME','PROUD','QUEEN','QUICK','REACH','READY','RIGHT','ROUGH','ROUTE','ROYAL','SCALE','SCORE','SERVE','SHARE','SHARP','SHEEP','SHELF','SHIFT','SHIRT','SHORT','SIGHT','SILVER','SKILL','SOUND','SOUTH','SPACE','SPEAK','SPEED','SPORT','STAND','START','STEAM','STILL','STOCK','STORE','STUDY','STYLE','SUGAR','THANK','THINK','THREE','THROW','TOUCH','TOWER','TRACK','TRADE','TRAIL','TREAT','TREND','TRIAL','TRUCK','TRULY','UNDER','VALUE','VIDEO','VOICE','WASTE','WATCH','WHEEL','WHITE','WHOLE','WOMAN','WRITE','YOUNG'];
const VALID=new Set([...ANSWERS,...EXTRA]);
const epoch=Date.UTC(2026,0,1), now=new Date(), day=Math.floor((Date.UTC(now.getFullYear(),now.getMonth(),now.getDate())-epoch)/86400000), puzzle=Math.max(1,day+1), answer=ANSWERS[((day%ANSWERS.length)+ANSWERS.length)%ANSWERS.length];
const dateKey=`${now.getFullYear()}-${now.getMonth()+1}-${now.getDate()}`, saveKey='daily-letter-state', statsKey='daily-letter-stats';
let state={date:dateKey,guesses:[],current:'',ended:false,won:false};
try{const saved=JSON.parse(localStorage.getItem(saveKey));if(saved&&saved.date===dateKey)state={...state,...saved}}catch{}
let stats={played:0,wins:0,streak:0,best:0,lastPlayed:null};try{stats={...stats,...JSON.parse(localStorage.getItem(statsKey))}}catch{}
const board=document.querySelector('#board'), keyboard=document.querySelector('#keyboard'), message=document.querySelector('#message');
document.querySelector('#puzzleNumber').textContent=`Puzzle ${puzzle}`;document.querySelector('#today').textContent=now.toLocaleDateString(undefined,{month:'long',day:'numeric',year:'numeric'});document.querySelector('#today').dateTime=dateKey;
for(let r=0;r<6;r++){const row=document.createElement('div');row.className='row';row.role='row';for(let c=0;c<5;c++){const tile=document.createElement('div');tile.className='tile';tile.role='gridcell';tile.id=`t-${r}-${c}`;tile.setAttribute('aria-label',`Row ${r+1}, letter ${c+1}`);row.append(tile)}board.append(row)}
const rows=['QWERTYUIOP','ASDFGHJKL','ZXCVBNM'];rows.forEach((letters,i)=>{const row=document.createElement('div');row.className='key-row';if(i===2)row.append(makeKey('ENTER','Enter'));[...letters].forEach(l=>row.append(makeKey(l,l)));if(i===2)row.append(makeKey('⌫','Backspace'));keyboard.append(row)});
function makeKey(label,value){const b=document.createElement('button');b.className='key'+(label.length>1?' wide':'');b.textContent=label;b.dataset.key=value;b.setAttribute('aria-label',value);b.onclick=()=>input(value);return b}
function score(word){const out=Array(5).fill('absent'),left=answer.split('');for(let i=0;i<5;i++)if(word[i]===answer[i]){out[i]='correct';left[i]=null}for(let i=0;i<5;i++)if(out[i]!=='correct'){const p=left.indexOf(word[i]);if(p>=0){out[i]='present';left[p]=null}}return out}
function paint(){for(let r=0;r<6;r++){const word=state.guesses[r]||(r===state.guesses.length?state.current:'');for(let c=0;c<5;c++){const t=document.querySelector(`#t-${r}-${c}`);t.textContent=word[c]||'';t.className='tile'+(word[c]?' filled':'')}}state.guesses.forEach((word,r)=>{score(word).forEach((kind,c)=>{const t=document.querySelector(`#t-${r}-${c}`);t.className=`tile ${kind}`;t.setAttribute('aria-label',`${word[c]}, ${kind}`);const key=document.querySelector(`[data-key="${word[c]}"]`),rank={absent:1,present:2,correct:3};if(key&&rank[kind]>(rank[key.dataset.state]||0)){key.className=`key ${kind}`;key.dataset.state=kind}})});updateStats();if(state.ended)document.querySelector('#resultArea').hidden=false}
function input(key){if(state.ended)return;if(key==='Backspace'){state.current=state.current.slice(0,-1)}else if(key==='Enter'){submit();return}else if(/^[A-Z]$/.test(key)&&state.current.length<5){state.current+=key}paint()}
function submit(){if(state.current.length<5)return notify('Not enough letters');if(!VALID.has(state.current))return notify('Not in this word list');const row=state.guesses.length,word=state.current;state.guesses.push(word);state.current='';score(word).forEach((kind,c)=>setTimeout(()=>document.querySelector(`#t-${row}-${c}`).classList.add('reveal'),c*90));if(word===answer){state.ended=true;state.won=true;finish();setTimeout(()=>{notify(['Excellent!','Well done!','Lovely!','You found it!'][Math.min(row,3)]);openDialog('statsDialog')},750)}else if(state.guesses.length===6){state.ended=true;finish();setTimeout(()=>{notify(`Today’s word was ${answer}`);openDialog('statsDialog')},750)}localStorage.setItem(saveKey,JSON.stringify(state));paint()}
function finish(){if(stats.lastPlayed===dateKey)return;stats.played++;if(state.won){stats.wins++;const yesterday=new Date(now);yesterday.setDate(yesterday.getDate()-1);const y=`${yesterday.getFullYear()}-${yesterday.getMonth()+1}-${yesterday.getDate()}`;stats.streak=stats.lastPlayed===y?stats.streak+1:1;stats.best=Math.max(stats.best,stats.streak)}else stats.streak=0;stats.lastPlayed=dateKey;localStorage.setItem(statsKey,JSON.stringify(stats));recordResult()}
let msgTimer;function notify(text){message.textContent=text;message.classList.add('show');clearTimeout(msgTimer);msgTimer=setTimeout(()=>message.classList.remove('show'),2200)}
function updateStats(){document.querySelector('#played').textContent=stats.played;document.querySelector('#winRate').textContent=stats.played?Math.round(stats.wins/stats.played*100):0;document.querySelector('#streak').textContent=stats.streak;document.querySelector('#best').textContent=stats.best;if(state.ended)document.querySelector('#resultText').textContent=state.won?`Solved in ${state.guesses.length} of 6 guesses`:`Better luck tomorrow`}
function result(){const grid=state.guesses.map(w=>score(w).map(x=>x==='correct'?'🟩':x==='present'?'🟨':'⬜').join('')).join('\n');return `Daily Letter ${puzzle} ${state.won?state.guesses.length:'X'}/6\n\n${grid}`}
document.querySelector('#shareButton').onclick=async()=>{const text=result();try{if(navigator.share)await navigator.share({text});else{await navigator.clipboard.writeText(text);notify('Result copied!')}}catch{}}
function openDialog(id){document.querySelector(`#${id}`).showModal()}document.querySelector('#helpButton').onclick=()=>openDialog('helpDialog');document.querySelector('#statsButton').onclick=()=>openDialog('statsDialog');document.querySelector('#settingsButton').onclick=()=>openDialog('settingsDialog');document.querySelector('#runAdButton').onclick=()=>openDialog('adDialog');document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>document.querySelector(`#${b.dataset.close}`).close());document.querySelectorAll('dialog').forEach(d=>d.onclick=e=>{if(e.target===d)d.close()});
const sideMenu=document.querySelector('#sideMenu'),menuScrim=document.querySelector('#menuScrim');function setMenu(open){sideMenu.classList.toggle('open',open);sideMenu.setAttribute('aria-hidden',String(!open));menuScrim.hidden=!open;if(open)document.querySelector('#closeMenu').focus()}document.querySelector('#menuButton').onclick=()=>setMenu(true);document.querySelector('#closeMenu').onclick=()=>setMenu(false);menuScrim.onclick=()=>setMenu(false);
let hintUsed=state.hintUsed||false;function giveHint(){setMenu(false);if(state.ended)return notify('Puzzle already complete');if(hintUsed)return notify('Today’s hint is already used');const available=[0,1,2,3,4].filter(i=>!state.guesses.some(g=>g[i]===answer[i]));const pos=available.length?available[Math.floor(Math.random()*available.length)]:0;hintUsed=true;state.hintUsed=true;localStorage.setItem(saveKey,JSON.stringify(state));notify(`Hint: letter ${pos+1} is ${answer[pos]}`)}document.querySelector('#hintButton').onclick=giveHint;
document.querySelectorAll('[data-menu-action]').forEach(b=>b.onclick=()=>{const a=b.dataset.menuAction;if(a==='today')setMenu(false);if(a==='hint')giveHint();if(a==='help'){setMenu(false);openDialog('helpDialog')}if(a==='stats'){setMenu(false);openDialog('statsDialog')}if(a==='settings'){setMenu(false);openDialog('settingsDialog')}if(a==='quick'){setMenu(false);openDialog('quickHelpDialog')}if(a==='account'){setMenu(false);paintProfile();openDialog('accountDialog')}});
const prefs=JSON.parse(localStorage.getItem('daily-letter-prefs')||'{}');function setPref(name,on){document.body.classList.toggle(name,on);const button=document.querySelector(name==='large-type'?'#largeTypeToggle':'#contrastToggle');button.setAttribute('aria-checked',String(on));prefs[name]=on;localStorage.setItem('daily-letter-prefs',JSON.stringify(prefs))}setPref('large-type',!!prefs['large-type']);setPref('high-contrast',!!prefs['high-contrast']);document.querySelector('#largeTypeToggle').onclick=e=>setPref('large-type',e.currentTarget.getAttribute('aria-checked')!=='true');document.querySelector('#contrastToggle').onclick=e=>setPref('high-contrast',e.currentTarget.getAttribute('aria-checked')!=='true');
document.addEventListener('keydown',e=>{if(document.querySelector('dialog[open]')){if(e.key==='Escape')return}else if(e.key==='Enter')input('Enter');else if(e.key==='Backspace')input('Backspace');else{const k=e.key.toUpperCase();if(/^[A-Z]$/.test(k))input(k)}});
paint();

// Quick help, themes, and a device-only profile. A secure external login must be
// connected to an OAuth provider and is intentionally not simulated here.
document.querySelector('#quickHelpButton').onclick=()=>openDialog('quickHelpDialog');
document.querySelector('#quickHintAction').onclick=()=>{document.querySelector('#quickHelpDialog').close();giveHint()};
document.querySelector('#rulesAction').onclick=()=>{document.querySelector('#quickHelpDialog').close();openDialog('helpDialog')};
const starterIdeas=['ARISE','BREAD','CLOUD','GRACE','HOUSE','OCEAN','PLANT','SHINE','STONE','TRAIN'];
document.querySelector('#ideaAction').onclick=()=>{document.querySelector('#quickHelpDialog').close();notify(`Try starting with ${starterIdeas[puzzle%starterIdeas.length]}`)};

const themeNames=['classic','ocean','forest'];
function setTheme(theme){theme=themeNames.includes(theme)?theme:'classic';document.body.classList.remove('theme-ocean','theme-forest');if(theme!=='classic')document.body.classList.add(`theme-${theme}`);prefs.theme=theme;localStorage.setItem('daily-letter-prefs',JSON.stringify(prefs));document.querySelectorAll('[data-theme]').forEach(b=>b.classList.toggle('selected',b.dataset.theme===theme))}
setTheme(prefs.theme||'classic');document.querySelectorAll('[data-theme]').forEach(b=>b.onclick=()=>setTheme(b.dataset.theme));

const sessionKey='daily-letter-session';let profile=null;
async function api(action,data){
  const response=await fetch('/.netlify/functions/api?action='+encodeURIComponent(action),{method:data?'POST':'GET',headers:data?{'Content-Type':'application/json'}:{},body:data?JSON.stringify(data):undefined,credentials:'same-origin'});
  let result={};try{result=await response.json()}catch{}
  if(!response.ok)throw new Error(result.error||'Something went wrong. Please try again.');
  return result;
}
function signedIn(){return !!profile}
function paintProfile(){const active=signedIn();document.querySelector('#signedOutView').hidden=active;document.querySelector('#signedInView').hidden=!active;document.querySelector('#accountLabel').textContent=active?'@'+profile.username:'Account';const initial=active?profile.firstName.trim().charAt(0).toUpperCase():'A';document.querySelector('#accountAvatar').textContent=initial;document.querySelector('#profileAvatar').textContent=initial;if(active){document.querySelector('#profileGreeting').textContent=`Hello, ${profile.firstName}!`;document.querySelector('#profileUsernameDisplay').textContent=`Player ID: @${profile.username}`}}
document.querySelector('#accountButton').onclick=()=>{paintProfile();openDialog('accountDialog')};
function makeUsername(){const first=document.querySelector('#profileFirstName').value||'player',last=document.querySelector('#profileLastName').value||'';const base=(first+last).toLowerCase().replace(/[^a-z0-9]/g,'').slice(0,16)||'player';return `${base}${Math.floor(100+Math.random()*900)}`}
function suggestUsername(){const field=document.querySelector('#profileUsername');if(!field.value)field.value=makeUsername()}
document.querySelector('#generateUsernameButton').onclick=()=>{document.querySelector('#profileUsername').value=makeUsername();document.querySelector('#profileUsername').focus()};
['#profileFirstName','#profileLastName'].forEach(selector=>document.querySelector(selector).addEventListener('blur',suggestUsername));
document.querySelector('#profilePhone').addEventListener('input',e=>{const digits=e.target.value.replace(/\D/g,'').slice(0,10);e.target.value=digits.length>6?`(${digits.slice(0,3)}) ${digits.slice(3,6)}-${digits.slice(6)}`:digits.length>3?`(${digits.slice(0,3)}) ${digits.slice(3)}`:digits});
function showRegisterStatus(text,type=''){const box=document.querySelector('#registerStatus');box.textContent=text;box.className='form-status'+(type?' '+type:'')}
function setFormBusy(form,busy){form.classList.toggle('is-busy',busy);form.querySelectorAll('button,input,select').forEach(el=>el.disabled=busy);const label=form.querySelector('.button-label');if(label&&!busy&&!form.classList.contains('is-success'))label.textContent='Create My ID & Start Playing'}
document.querySelector('#registerForm').addEventListener('invalid',e=>{e.target.classList.add('field-error');showRegisterStatus('Please complete the highlighted field.','error')},true);
document.querySelectorAll('#registerForm input,#registerForm select').forEach(field=>field.addEventListener('input',()=>{field.classList.remove('field-error');if(document.querySelector('#registerStatus').classList.contains('error'))showRegisterStatus('')}));
document.querySelector('#registerForm').onsubmit=async e=>{e.preventDefault();const form=e.currentTarget;if(!form.reportValidity())return;showRegisterStatus('Securely creating your Player ID…','working');setFormBusy(form,true);try{const firstName=document.querySelector('#profileFirstName').value.trim(),lastName=document.querySelector('#profileLastName').value.trim();const result=await api('register',{firstName,lastName,age:Number(document.querySelector('#profileAge').value),phone:document.querySelector('#profilePhone').value.trim(),street:document.querySelector('#profileStreet').value.trim(),city:document.querySelector('#profileCity').value.trim(),state:document.querySelector('#profileState').value,zip:document.querySelector('#profileZip').value.trim(),username:document.querySelector('#profileUsername').value.trim(),password:document.querySelector('#profilePassword').value,consent:document.querySelector('#profileConsent').checked});profile=result.profile;paintProfile();form.classList.add('is-success');form.querySelector('.button-label').textContent='Account created!';showRegisterStatus(`Welcome, @${profile.username}! Your account is ready.`,'success');setTimeout(()=>{document.querySelector('#accountDialog').close();notify('Player ID created — welcome!')},700)}catch(error){showRegisterStatus(error.message,'error');setFormBusy(form,false)}};
document.querySelector('#showLoginButton').onclick=()=>{document.querySelector('#registerForm').hidden=true;document.querySelector('#showLoginButton').hidden=true;document.querySelector('#loginForm').hidden=false};document.querySelector('#showRegisterButton').onclick=()=>{document.querySelector('#loginForm').hidden=true;document.querySelector('#registerForm').hidden=false;document.querySelector('#showLoginButton').hidden=false};
document.querySelector('#loginForm').onsubmit=async e=>{e.preventDefault();const form=e.currentTarget;if(!form.reportValidity())return;setFormBusy(form,true);try{const result=await api('login',{username:document.querySelector('#loginUsername').value.trim(),password:document.querySelector('#loginPassword').value});profile=result.profile;paintProfile();document.querySelector('#accountDialog').close();notify('Welcome back!')}catch(error){notify(error.message)}finally{setFormBusy(form,false)}};
document.querySelector('#logoutButton').onclick=async()=>{try{await api('logout',{})}catch{}profile=null;paintProfile();notify('Logged out')};
document.querySelector('#openSettingsFromAccount').onclick=()=>{document.querySelector('#accountDialog').close();openDialog('settingsDialog')};
async function recordResult(){if(!profile||!state.ended)return;try{await api('result',{puzzleNumber:puzzle,guesses:state.guesses.length,won:state.won})}catch{}}
async function startAccount(){try{const result=await api('me');profile=result.profile||null}catch{profile=null}paintProfile();if(!profile)setTimeout(()=>openDialog('accountDialog'),250);else{api('heartbeat',{}).catch(()=>{});setInterval(()=>api('heartbeat',{}).catch(()=>{}),120000)}}
startAccount();
